/// Per-die Tensix compute grid plus the board's die count. The scheduler
/// plans one die at a time; totalCores reports the whole product.
struct CoreGrid {
  int64_t gridX = 0;
  int64_t gridY = 0;
  int64_t chips = 1;

  int64_t totalCores() const { return chips * gridX * gridY; }
};

/// One published device specification. The values are static planning
/// inputs, never measured performance.
struct DeviceSpec {
  const char *name;
  const char *arch;
  CoreGrid computeGrid;
  int64_t l1UsableBytes;
  int64_t l1NominalBytes;
  int64_t tileHeight;
  int64_t tileWidth;
  int64_t tileBytes;
  int64_t clockHz;
  int64_t flopsPerCyclePerCore;
  int64_t dramBytes;
  int64_t dramBandwidthBytesPerSecond;
  int64_t nocCount;
  int64_t nocFlitBytes;
  int64_t nocMaxBurstBytes;
  int64_t nocBytesPerCyclePerDirection;
  int64_t powerWatts;

  /// Bytes of per-core L1 left for circular buffers after reserveBytes of
  /// code, stack, and runtime bookkeeping. Never negative.
  int64_t cbBudget(int64_t reserveBytes) const;
};

inline int64_t DeviceSpec::cbBudget(int64_t reserveBytes) const {
  const int64_t budget = l1UsableBytes - reserveBytes;
  if (budget <= 0) {
    return 0;
  }
  return budget;
}

