inline llvm::ArrayRef<DeviceSpec> allDevices() {
  return llvm::ArrayRef<DeviceSpec>(kDevices, kNumDevices);
}

/// One alternate product name accepted by lookup().
struct DeviceAlias {
  const char *alias;
  const char *device;
};

constexpr std::size_t kNumAliases = 6;

inline constexpr DeviceAlias kAliases[] = {
    DeviceAlias{"n150d", "n150"},
    DeviceAlias{"n150s", "n150"},
    DeviceAlias{"n300d", "n300"},
    DeviceAlias{"n300s", "n300"},
    DeviceAlias{"bh_p100a", "p100a"},
    DeviceAlias{"bh_p150a", "p150a"},
};

/// Look up a device by name or alias. Returns nullptr for an unknown name.
inline const DeviceSpec *lookup(llvm::StringRef name) {
  for (const DeviceSpec &spec : allDevices()) {
    if (name == spec.name) {
      return &spec;
    }
  }
  for (const DeviceAlias &alias : kAliases) {
    if (name == alias.alias) {
      return lookup(alias.device);
    }
  }
  return nullptr;
}

inline llvm::StringRef defaultDeviceName() { return kDefaultDeviceName; }

inline const DeviceSpec *defaultDevice() { return lookup(defaultDeviceName()); }

/// Comma-separated list for diagnostics about an unknown device name.
inline llvm::StringRef validDeviceNames() { return kValidDeviceNames; }

